import { useSyncExternalStore } from 'react';
import { AppSettings, SynthPreset, PresetState, PlayMode, StoreState } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_NORMAL_PRESET, DEFAULT_LATCH_PRESET, DEFAULT_STRUM_PRESET, DEFAULT_BRASS_PRESET, DEFAULT_KEYS_PRESET, DEFAULT_PERCUSSION_PRESET, DEFAULT_USER_BANK, DEFAULT_COLORS, REVERB_DEFAULTS } from '../constants';
import { XmlService } from './XmlService';

const SETTINGS_KEY = 'prismatonal_settings_v6'; // Bumped version for grid mask migration
const PRESET_KEY = 'prismatonal_presets_v5';
const USER_BANK_KEY = 'prismatonal_user_bank_v1';

class PrismaStore {
  private state: StoreState;
  private listeners: Set<() => void> = new Set();

  constructor() {
    // Hardware-aware Smart Default Polyphony & Quality
    const cores = navigator.hardwareConcurrency || 4;
    let safePolyphony = 8;
    let safeOversampling = false; 

    if (cores <= 4) {
        safePolyphony = 6;
    }
    else if (cores >= 8) {
        safePolyphony = 12;
    }

    // Load Settings with Robust Deep Merge
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    let loadedSettings: AppSettings = { ...DEFAULT_SETTINGS, polyphony: safePolyphony, enableOversampling: safeOversampling };

    if (savedSettings) {
        try {
            const parsed = JSON.parse(savedSettings);
            loadedSettings = {
                ...DEFAULT_SETTINGS,
                ...parsed,
                // Ensure polyphony is not ridiculously high if loading old settings on a weak device
                polyphony: (parsed.polyphony && parsed.polyphony > 16 && cores <= 4) ? 8 : (parsed.polyphony || safePolyphony),
                enableOversampling: (parsed.enableOversampling !== undefined) ? parsed.enableOversampling : safeOversampling,
                layoutApproach: parsed.layoutApproach || DEFAULT_SETTINGS.layoutApproach,
                enabledGridMask: parsed.enabledGridMask || DEFAULT_SETTINGS.enabledGridMask, // Load Mask
                colors: { ...DEFAULT_COLORS, ...(parsed.colors || {}) }, 
                uiPositions: { ...DEFAULT_SETTINGS.uiPositions, ...(parsed.uiPositions || {}) },
                arpeggios: parsed.arpeggios || DEFAULT_SETTINGS.arpeggios,
                arpBpm: parsed.arpBpm || DEFAULT_SETTINGS.arpBpm,
                wavetableSize: parsed.wavetableSize || DEFAULT_SETTINGS.wavetableSize,
                interpolationType: parsed.interpolationType || DEFAULT_SETTINGS.interpolationType
            };

            // Migrate stored chords to ensure soundConfig (if present) is valid
            if (loadedSettings.savedChords) {
                loadedSettings.savedChords = loadedSettings.savedChords.map(c => {
                    if (c.soundConfig) {
                        return { ...c, soundConfig: this.migratePreset(c.soundConfig) };
                    }
                    return c;
                });
            }

        } catch (e) {
            console.error("Failed to parse settings, reverting to defaults", e);
            loadedSettings = { ...DEFAULT_SETTINGS, polyphony: safePolyphony, enableOversampling: safeOversampling };
        }
    }

    // Load Presets
    const savedPresets = localStorage.getItem(PRESET_KEY);
    let loadedPresets: PresetState;

    if (savedPresets) {
        try {
            const parsed = JSON.parse(savedPresets);
            loadedPresets = {
                normal: this.migratePreset(parsed.normal || DEFAULT_NORMAL_PRESET),
                latch: this.migratePreset(parsed.latch || DEFAULT_LATCH_PRESET),
                strum: this.migratePreset(parsed.strum || DEFAULT_STRUM_PRESET),
                brass: this.migratePreset(parsed.brass || parsed.voice || DEFAULT_BRASS_PRESET),
                keys: this.migratePreset(parsed.keys || parsed.arpeggio || DEFAULT_KEYS_PRESET), 
                percussion: this.migratePreset(parsed.percussion || DEFAULT_PERCUSSION_PRESET)
            };

            if (loadedPresets.keys.name === DEFAULT_NORMAL_PRESET.name && DEFAULT_KEYS_PRESET.name !== DEFAULT_NORMAL_PRESET.name) {
                if (loadedPresets.keys.name === 'Analog Strings') {
                    loadedPresets.keys = JSON.parse(JSON.stringify(DEFAULT_KEYS_PRESET));
                }
            }

        } catch (e) {
            loadedPresets = {
                normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                brass: JSON.parse(JSON.stringify(DEFAULT_BRASS_PRESET)),
                keys: JSON.parse(JSON.stringify(DEFAULT_KEYS_PRESET)),
                percussion: JSON.parse(JSON.stringify(DEFAULT_PERCUSSION_PRESET))
            };
        }
    } else {
        loadedPresets = {
            normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
            latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
            strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
            brass: JSON.parse(JSON.stringify(DEFAULT_BRASS_PRESET)),
            keys: JSON.parse(JSON.stringify(DEFAULT_KEYS_PRESET)),
            percussion: JSON.parse(JSON.stringify(DEFAULT_PERCUSSION_PRESET))
        };
    }

    // Load User Bank
    const savedUserBank = localStorage.getItem(USER_BANK_KEY);
    let loadedUserBank: SynthPreset[] = DEFAULT_USER_BANK;
    if (savedUserBank) {
        try {
            const parsed = JSON.parse(savedUserBank);
            if (Array.isArray(parsed)) {
                loadedUserBank = parsed.map(p => this.migratePreset(p));
            }
        } catch(e) {
            loadedUserBank = DEFAULT_USER_BANK;
        }
    }

    this.state = {
        settings: loadedSettings,
        presets: loadedPresets,
        userBank: loadedUserBank
    };
  }

  // Helper to ensure loaded presets have all required fields (migration from old versions)
  private migratePreset(p: any): SynthPreset {
      if (!p) return DEFAULT_NORMAL_PRESET;

      const safe: SynthPreset = {
          ...DEFAULT_NORMAL_PRESET, // Fallback defaults
          ...p,
          osc1: { ...DEFAULT_NORMAL_PRESET.osc1, ...(p.osc1 || {}) },
          osc2: { ...DEFAULT_NORMAL_PRESET.osc2, ...(p.osc2 || {}) },
          osc3: { ...DEFAULT_NORMAL_PRESET.osc3, ...(p.osc3 || {}) },
          modMatrix: p.modMatrix || []
      };

      // Ensure Reverb Defaults if missing
      if (safe.reverbType && (safe.reverbSize === undefined || safe.reverbDamping === undefined || safe.reverbDiffusion === undefined)) {
          const defaults = REVERB_DEFAULTS[safe.reverbType] || REVERB_DEFAULTS['hall'];
          if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
          if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
          if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;
      }

      return safe;
  }

  // --- ACTIONS ---

  updateSettings = (partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => {
    const current = this.state.settings;
    let next: AppSettings;

    if (typeof partial === 'function') {
      next = partial(current);
    } else {
      next = { ...current, ...partial };
    }

    if (next === current) return;

    // Apply Update
    this.state = { ...this.state, settings: next };

    // Persist with Safety Check
    try {
        localStorage.setItem(SETTINGS_KEY, JSON.stringify(next));
    } catch (e: any) {
        if (e.name === 'QuotaExceededError' && next.backgroundImageData) {
            console.warn("Storage quota exceeded due to background image. Saving partial settings.");
            // If failed, try to save without the heavy background image
            const safeSettings = { ...next, backgroundImageData: null };
            try {
                localStorage.setItem(SETTINGS_KEY, JSON.stringify(safeSettings));
                alert("Storage Limit Warning: Background image was too large to save. Other settings have been saved. Please use a smaller image.");
            } catch (innerE) {
                console.error("Critical storage failure", innerE);
            }
        } else {
            console.warn("Settings storage limit reached. Changes saved to session only.", e);
        }
    }
    this.notify();
  };

  setPreset = (mode: PlayMode, newPreset: SynthPreset) => {
    const current = this.state.presets[mode];
    if (newPreset === current) return;

    const nextPresets = { ...this.state.presets, [mode]: newPreset };
    this.state = { ...this.state, presets: nextPresets };

    try {
        localStorage.setItem(PRESET_KEY, JSON.stringify(nextPresets));
    } catch (e) {
        console.warn("Preset storage limit reached. Changes saved to session only.");
    }
    this.notify();
  };

  saveUserPatch = (slotIndex: number, preset: SynthPreset) => {
      if (slotIndex < 0 || slotIndex >= 100) return;
      const newBank = [...this.state.userBank];
      newBank[slotIndex] = { ...preset, category: 'User' };

      this.state = { ...this.state, userBank: newBank };

      try {
          localStorage.setItem(USER_BANK_KEY, JSON.stringify(newBank));
      } catch (e) {
          console.warn("Bank storage limit reached. Changes saved to session only.");
          alert("Storage Limit Reached. Export XML to save your work.");
      }
      this.notify();
  };

  exportXML = () => {
      const xml = XmlService.exportState(this.state);
      XmlService.downloadFile(xml);
  };

  importXML = async (file: File) => {
      try {
          const partial = await XmlService.parseImport(file);
          if (partial) {
              const nextState = { ...this.state, ...partial };

              // Migrate imported data
              if (nextState.presets) {
                  nextState.presets = {
                      normal: this.migratePreset(nextState.presets.normal),
                      latch: this.migratePreset(nextState.presets.latch),
                      strum: this.migratePreset(nextState.presets.strum),
                      brass: this.migratePreset(nextState.presets.brass || (nextState.presets as any).voice),
                      keys: this.migratePreset(nextState.presets.keys || (nextState.presets as any).arpeggio),
                      percussion: this.migratePreset(nextState.presets.percussion || DEFAULT_PERCUSSION_PRESET)
                  };
              }
              if (nextState.userBank) {
                  nextState.userBank = nextState.userBank.map(p => this.migratePreset(p));
              }
              if (nextState.settings && nextState.settings.savedChords) {
                  nextState.settings.savedChords = nextState.settings.savedChords.map(c => {
                      if (c.soundConfig) return { ...c, soundConfig: this.migratePreset(c.soundConfig) };
                      return c;
                  });
              }

              // Try saving imported data to local storage, handle quotas
              try {
                  localStorage.setItem(SETTINGS_KEY, JSON.stringify(nextState.settings));
                  localStorage.setItem(PRESET_KEY, JSON.stringify(nextState.presets));
                  localStorage.setItem(USER_BANK_KEY, JSON.stringify(nextState.userBank));
              } catch (e) {
                  console.warn("Import exceeded local storage quota. Data loaded into session memory only.");
                  alert("Warning: Import successful, but data exceeds browser storage limits. It will persist only for this session unless you export again.");
              }

              this.state = nextState as StoreState; // Cast to ensure type safety after partial merge
              this.notify();
              return true;
          }
      } catch (e) {
          console.error(e);
          alert("Failed to import XML file.");
      }
      return false;
  };

  // --- SUBSCRIPTION ---
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = () => {
    return this.state;
  };

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const store = new PrismaStore();

export function useStore() {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);

  return {
    settings: state.settings,
    presets: state.presets, 
    userBank: state.userBank,
    updateSettings: store.updateSettings,
    setPreset: store.setPreset,
    saveUserPatch: store.saveUserPatch,
    exportXML: store.exportXML,
    importXML: store.importXML
  };
}

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';
import { GRID_IDENTITIES } from '../constants';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getOddLimit = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 0) temp /= 2;
  return temp;
};

export class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  div(other: Fraction): Fraction {
    return new Fraction(this.n * other.d, this.d * other.n);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (nn === 0 || dd === 0) return new Fraction(0, 1);
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }

  valueOf() {
      return this.n / this.d;
  }
}

const PRIMES = [3, 5, 7, 11, 13];
// Prime Ratios for Line Checking (Standard Steps)
const PRIME_STEPS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// Decompose a number into prime powers for [3, 5, 7, 11, 13]
// Returns array [p3, p5, p7, p11, p13]
const getPrimeFactors = (n: number): number[] => {
    let temp = n;
    const result = [0, 0, 0, 0, 0];

    // Remove factors of 2 (Octaves don't affect lattice position X)
    while (temp % 2 === 0 && temp > 0) temp /= 2;

    PRIMES.forEach((p, idx) => {
        while (temp % p === 0 && temp > 0) {
            result[idx]++;
            temp /= p;
        }
    });

    // Handle remaining composite factors roughly if needed, 
    // but for the defined GRID_IDENTITIES (1,3,5,7,9,11,13,15) this covers all bases.
    // 9 is 3^2, 15 is 3*5.

    return result;
};

// Calculate vector for a Fraction (Numerator Vector - Denominator Vector)
const getFractionVector = (frac: Fraction): number[] => {
    const nVec = getPrimeFactors(frac.n);
    const dVec = getPrimeFactors(frac.d);
    return nVec.map((val, i) => val - dVec[i]);
};

// --- Reconstruction Helper ---

export const reconstructNode = (id: string, settings: AppSettings): LatticeNode | null => {
    try {
        const parts = id.split(':');
        // Legacy IDs might be different, but Matrix IDs are usually "coords:octave"
        // However, with Matrix generation, we might want to support reconstruction for 
        // persistent latches even if they fall outside the current mask.

        if (parts.length !== 2) return null;

        const coordStr = parts[0];
        const octStr = parts[1];
        const coords = coordStr.split(',').map(Number);
        const octave = parseInt(octStr);

        if (coords.some(isNaN) || isNaN(octave)) return null;

        // Rebuild Fraction from Coords
        // This is the reverse of decomposition. 
        let frac = new Fraction(1, 1);
        PRIMES.forEach((gen, idx) => {
            const val = coords[idx] || 0;
            // @ts-ignore
            const gRat = PRIME_STEPS[gen];
            for(let i=0; i<Math.abs(val); i++) {
                frac = val > 0 ? frac.mul(gRat).normalize() : frac.mul(new Fraction(gRat.d, gRat.n)).normalize();
            }
        });

        // Apply octave shift
        frac = frac.shiftOctave(octave);

        const ratio = frac.n / frac.d;
        const { x, y } = projectCoordinates(coords, ratio, settings.latticeAspectRatio, settings.layoutApproach);

        return {
            id,
            coords,
            octave,
            ratio,
            n: frac.n,
            d: frac.d,
            label: `${frac.n}/${frac.d}`,
            x, y,
            limitTop: getOddLimit(frac.n),
            limitBottom: getOddLimit(frac.d),
            maxPrime: Math.max(getOddLimit(frac.n), getOddLimit(frac.d)),
            isGhost: true
        };
    } catch (e) {
        return null;
    }
};

// --- Main Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  const nodesMap = new Map<string, LatticeNode>();
  const mask = settings.enabledGridMask;
  const identities = GRID_IDENTITIES;

  // If mask is invalid size, fallback to default (should be handled in Store, but safety first)
  const safeMask = (mask && mask.length === 64) ? mask : new Array(64).fill(false);

  // Pre-calculate vectors for the 8 identities to speed up the loop
  const identityVectors = identities.map(id => getFractionVector(new Fraction(id.n, id.d)));

  // Iterate through all Modulation Origins (Poly-Modulation support)
  generationOrigins.forEach(origin => {

      // Calculate origin ratio to multiply
      // (Used for n/d labeling logic if we wanted absolute labels, 
      // but usually we keep labels relative to 1/1 or just display the calculated ratio)

      // We iterate the 8x8 Matrix
      for (let i = 0; i < 64; i++) {
          if (!safeMask[i]) continue;

          const row = Math.floor(i / 8); // Otonality (Numerator)
          const col = i % 8;             // Utonality (Denominator)

          const otonalIdentity = identities[row];
          const utonalIdentity = identities[col];
          const oVec = identityVectors[row];
          const uVec = identityVectors[col];

          // Resulting Ratio = Otonal / Utonal
          const baseFrac = new Fraction(otonalIdentity.n, otonalIdentity.d)
                            .div(new Fraction(utonalIdentity.n, utonalIdentity.d))
                            .normalize();

          // Resulting Vector = OtonalVec - UtonalVec + OriginVec
          const combinedCoords = oVec.map((val, idx) => val - uVec[idx] + (origin.coords[idx] || 0));

          // Generate for Octaves (usually -1, 0, +1 around center for lattice view flexibility)
          // The "Matrix" defines the chroma, we might want to see it in a few octaves
          const octaveRange = 1; 

          for (let oct = origin.octave - octaveRange; oct <= origin.octave + octaveRange; oct++) {

              // Adjust coords for projection if specific lattice logic requires it?
              // Standard lattice: Coords define X/Y. Octave defines Y offset.
              // We pass the coords directly.

              // Unique ID based on absolute coordinates
              const id = `${combinedCoords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const finalFrac = baseFrac.shiftOctave(oct - origin.octave); // Adjust for loop relative to origin
                  // Note: The origin's own octave shift is conceptual; 
                  // usually modulation keeps 1/1 at the new center visually.
                  // If we want absolute frequency ratios, we must multiply by origin's scalar ratio.
                  // For the UI Label (n/d), we usually display the relationship *within* the matrix.
                  // Let's stick to the matrix ratio normalized.

                  const ratioValue = finalFrac.valueOf();

                  // Project
                  const { x, y } = projectCoordinates(combinedCoords, ratioValue, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: combinedCoords,
                      octave: oct,
                      ratio: ratioValue, // This ratio is relative to global 1/1 if origin was 1/1
                      n: finalFrac.n,
                      d: finalFrac.d,
                      label: `${finalFrac.n}/${finalFrac.d}`,
                      x, y,
                      limitTop: getOddLimit(finalFrac.n),
                      limitBottom: getOddLimit(finalFrac.d),
                      maxPrime: Math.max(getOddLimit(finalFrac.n), getOddLimit(finalFrac.d)),
                      originIndex: 0 // Could track which origin generated it
                  });
              }
          }
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Connect Lines based on Prime Intervals (Lattice Logic)
  // We check every node against every other to see if they are a 'prime step' away.
  // Optimization: Only check nodes within a reasonable coordinate distance? 
  // Given max 64 nodes * 3 octaves = ~200 nodes, $N^2$ is fine (40k checks).

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          // Check for neighbor with coord + 1 in this prime dimension
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          // Check same octave and adjacent octaves (3/2 might cross octave boundary in some representations, 
          // but here we define connection by coordinate adjacency. 
          // A step of "3" is a coordinate change of +1 in index 0. 
          // The octave of the target might be different if we normalized the ratio?
          // ReconstructNode logic uses explicit coords.
          // Let's look for exact coordinate matches in the map.

          // Note: In Just Intonation, moving by a prime ratio often shifts the pitch 
          // such that we might need to normalize the octave to find the neighbor if we were strictly grid-based.
          // But here, `coords` tracks the prime powers directly. 
          // So [1,0,0] is 3/2. [2,0,0] is 9/8. 
          // A connection exists if coords differ by exactly 1 in one dimension.
          // The node at `coordKey` might be in any octave.

          // However, for visual clarity, we usually only connect nodes that are relatively close in pitch (Y axis).
          // We'll check the current octave and maybe +/- 1.

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);

              if (target) {
                  // Verify the musical interval is actually the prime (ignoring octave)
                  // Ratio T / S
                  const ratio = target.ratio / node.ratio;
                  // Normalize ratio to 1-2
                  let normRatio = ratio;
                  while (normRatio < 1.0) normRatio *= 2;
                  while (normRatio >= 2.0) normRatio /= 2;

                  // Expected Prime Ratio (e.g. 1.5 for 3)
                  // @ts-ignore
                  const pFrac = PRIME_STEPS[prime];
                  const pVal = pFrac.n / pFrac.d;

                  // Allow slight float error
                  if (Math.abs(normRatio - pVal) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, 
                          sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

import React, { useMemo } from 'react';
import { AppSettings, TuningSystem, LayoutApproach } from '../../types';
import { NumberInput } from './SettingsWidgets';
import { GRID_IDENTITIES, DEFAULT_COLORS } from '../../constants';
import { Fraction, getOddLimit } from '../../services/LatticeService';

interface Props {
    settings: AppSettings;
    updateSettings: (s: Partial<AppSettings>) => void;
}

const TonalityTab: React.FC<Props> = ({ settings, updateSettings }) => {

    const handleChange = (key: keyof AppSettings, value: any) => updateSettings({ [key]: value });

    const toggleGridCell = (index: number) => {
        const newMask = [...settings.enabledGridMask];
        newMask[index] = !newMask[index];
        updateSettings({ enabledGridMask: newMask });
    };

    const setMatrixPreset = (type: 'all' | 'none' | 'diagonal' | 'square' | 'cross') => {
        const newMask = new Array(64).fill(false);
        for(let i=0; i<64; i++) {
            const row = Math.floor(i / 8);
            const col = i % 8;

            if (type === 'all') newMask[i] = true;
            if (type === 'diagonal') {
                if (row === col) newMask[i] = true; // 1/1 diagonal
            }
            if (type === 'square') {
                // First 3 identities (1, 5, 3) 3x3 grid
                if (row < 3 && col < 3) newMask[i] = true;
            }
            if (type === 'cross') {
                // 1/1 Row and 1/1 Col (Identity 0)
                if (row === 0 || col === 0) newMask[i] = true;
            }
        }
        updateSettings({ enabledGridMask: newMask });
    };

    const renderLayoutSelector = (system: TuningSystem) => {
        let options: { value: LayoutApproach; label: string }[] = [];

        switch (system) {
          case 'ji':
            options = [
              { value: 'lattice', label: 'Tonality Lattice' },
              { value: 'diamond', label: 'Tonality Diamond' },
            ];
            break;
          case 'et':
            options = [
              { value: 'et_wheel', label: 'Chromatic Wheel' },
              { value: 'et_grid', label: 'Keyboard Grid' },
              { value: 'et_row', label: 'Linear Strip' },
            ];
            break;
          case 'indian':
            options = [
              { value: 'indian_circle', label: 'Shruti Circle' },
              { value: 'indian_thaat', label: 'Thaat Map' },
            ];
            break;
          case 'pythagorean':
            options = [
              { value: 'pyth_spiral', label: 'Spiral of Fifths' },
              { value: 'pyth_row', label: 'Linear Stack' },
            ];
            break;
        }

        const isValid = options.some(o => o.value === settings.layoutApproach);
        if (!isValid && options.length > 0) {
          setTimeout(() => handleChange('layoutApproach', options[0].value), 0);
        }

        return (
          <div className="bg-slate-900/60 p-4 rounded-lg border border-indigo-500/20 mb-6">
              <label className="block text-[10px] text-indigo-400 font-bold uppercase mb-2 tracking-widest">Layout & Orientation</label>
              <div className="flex gap-2">
                  <select 
                      value={settings.layoutApproach} 
                      onChange={(e) => {
                          const newLayout = e.target.value as LayoutApproach;
                          let newSpacing = settings.buttonSpacingScale;

                          if (newLayout === 'diamond') newSpacing = 0.756; 
                          else if (newLayout === 'lattice') newSpacing = 1.89; 

                          updateSettings({ 
                              layoutApproach: newLayout,
                              buttonSpacingScale: newSpacing
                          });
                      }}
                      className="flex-1 bg-slate-800 border border-slate-600 rounded p-1.5 text-[10px] text-white focus:outline-none focus:border-indigo-500"
                  >
                      {options.map(opt => (
                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                      ))}
                  </select>
              </div>
              <p className="text-[9px] text-slate-500 mt-2 italic">Governs the geometric arrangement and orientation of pitch nodes.</p>
          </div>
        );
    };

    const renderBaseFrequency = () => (
        <div className="bg-slate-900/60 p-4 rounded-lg border border-blue-500/20 mb-6">
            <div className="flex justify-between items-center mb-2">
              <h3 className="font-bold text-blue-400 text-xs uppercase tracking-widest">Global Tuning Center</h3>
              <span className="text-[9px] text-slate-500 font-mono">1/1 REFERENCE</span>
            </div>
            <NumberInput value={settings.baseFrequency} min={20} max={15000} suffix="Hz" onChange={(val) => handleChange('baseFrequency', val)} />
            <p className="text-[10px] text-slate-500 mt-2 italic">Sets the fundamental frequency for the origin node across all tuning modes.</p>
        </div>
    );

    // Memoize cell data to avoid re-calculating fractions on every render
    const matrixCells = useMemo(() => {
        const cells = [];
        for(let i=0; i<64; i++) {
            const row = Math.floor(i / 8);
            const col = i % 8;
            const otonal = GRID_IDENTITIES[row]; // Numerator source
            const utonal = GRID_IDENTITIES[col]; // Denominator source

            // Calc Ratio: (Otonal / Utonal)
            // Identity is {n, d}
            const frac = new Fraction(otonal.n, otonal.d).div(new Fraction(utonal.n, utonal.d)).normalize();
            const limit = Math.max(getOddLimit(frac.n), getOddLimit(frac.d));
            const color = DEFAULT_COLORS[limit] || '#ffffff';

            cells.push({ index: i, label: `${frac.n}/${frac.d}`, color, limit });
        }
        return cells;
