    // 8x8 Grid. 
    // Row 0 is 1/1 Otonal Series (1, 5, 3, 7...)
    // Col 0 is 1/1 Utonal Series (1, 1/5, 1/3, 1/7...)
    const mask = Array(64).fill(false);

    // Enable a 3x3 Square by default to show both Otonal and Utonal directions
    // Identities: 1 (0), 5 (1), 3 (2)

    // Row 0 (1/1): 1, 5, 3
    mask[0] = true; mask[1] = true; mask[2] = true;

    // Row 1 (5/4): 5, 25/4, 15/4
    mask[8] = true; mask[9] = true; mask[10] = true;

    // Row 2 (3/2): 3, 15/4, 9/4
    mask[16] = true; mask[17] = true; mask[18] = true;

    return mask;
};

