    const att = Math.max(0.001, config.attack || 0.01);
    const dec = Math.max(0.001, config.decay || 0.1);
    const sus = config.sustain !== undefined ? config.sustain : 1.0;
    const rel = Math.max(0.001, config.release || 0.1);

