  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) }, osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) }, osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
